head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDBNF35019";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — bndMktactTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf35019.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_if_21", fn: function(){ return (String((dma_pageContext.get("bndMktactTpCd") ?? "")).substring(0, 1) === '1'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("bndApplId") ?? ""))); } },
        { childId: "__rb1", fn: function () { return String(String((dma_pageContext.get("retRsn") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_re_Request_onclick
 * @description btn_re_Request 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_re_Request_onclick = function(e){
    try {
        scwin.re_Request((String(((dma_pageContext.get("bndMktactTpCd") ?? "")) == null ? '' : ((dma_pageContext.get("bndMktactTpCd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("bndMktactTpCd") ?? "")) == null ? '' : ((dma_pageContext.get("bndMktactTpCd") ?? "")))))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf35019.btn_re_Request_onclick' }); }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf35019.btn_self_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name winClose
 * @description win Close 처리
 * @returns {void}
 * @hidden N
 */
scwin.winClose = function () {
    parent.$c.win.closePopup();
};

/**
 * @method
 * @name re_Request
 * @description re Request 처리
 * @param {*} mkt_cd mkt_cd
 * @returns {void}
 * @hidden N
 */
scwin.re_Request = function (mkt_cd) {
    if (mkt_cd === "112" || mkt_cd === "122" || mkt_cd === "132" || mkt_cd === "142") {
        $c.win.setPageFrameSrc($c.win.getFrame(), '/ui/jsp/JLDBNF10000.xml');
    } else {
        $c.win.setPageFrameSrc($c.win.getFrame(), '/ui/jsp/JLDBNF05000.xml');
    }
    $c.win.closePopup();
};
